import { useCallback, useEffect, useState, useMemo } from "react";
import styles from "./auto-sized-text.module.less";
import Icon, { IconName } from "@/core/components/primitives/icon/icon";
import { debounce } from "lodash-es";

type AutoSizedTextProps = {
  /** The element that the text will be sized to fit within. If omitted, the parent element is used. */
  wrapperElement?: HTMLDivElement | null;
  text: string;
  /**
   * The widest string to use for sizing, if different from the main text.
   * Useful to get same size of several rows.
   * Use `getWidestText()` to get the string
   */
  widestText?: string;
  /** Text to be stricken through, if different from the main text. Will be displayed with a line through it and before main text. */
  strikeThroughText?: string;
  /** Icon to be displayed before the text */
  icon?: IconName;
  /** Gap between items (icon, strikethhrough text and text) in percentage of font size (default is `20%`). */
  gap?: number;
  /**
   * Padding around the content in percentage of wrapper element size, given as a string with 1-4 values (same syntax order as in CSS) (default is `2%`).
   * Use padding mode to set which wrapper size value(s) to base this on, default is the wrapper width.
   * @example
   * - `2` --> 2% top/bottom/left/right
   * - `2 5` --> 2% top/bottom, 5% left/right
   * - `2 5 10` --> 2% top, 5% right/left, 10% bottom
   * - `2 5 10 15` --> 2% top, 5% right, 10% bottom, 15% left
   */
  padding?: string;
  /** What value padding is calculated by (default is `fixedWidth` (width)) \
   * The default in CSS is that the height of the wrapper is used if padding is set as percentage. \
   * Possible to use height instead, or to use dynamic values, i.e. height for top/bottom and width for left/right.
   * Useful for example when several elements are stacked in the same container and you want all children to have the same padding or based on the same value (example container height)
   *
   *
   * @example
   * All examples use: Height = 100px, Width = 1000px
   *
   * @example Width (always % of width 1000px)
   * - `2` --> 2% = 20px top/bottom/left/right
   * - `2 5` --> 2% = 20px top/bottom, 5% = 50px left/right
   *
   * @example Height (always % of height 100px)
   * - `2` --> 2% = 2px top/bottom/left/right
   * - `2 5` --> 2% = 2px top/bottom, 5% = 5px left/right
   *
   * @example Dynamic (% of height 100px and width 1000px)
   * - `2` --> 2% of height = 2px top/bottom, 2% of width = 20px left/right
   * - `2 5` --> 2% of height = 2px top/bottom, 5% of width = 50px left/right
   */
  paddingMode?: "fixedWidth" | "fixedHeight" | "dynamic";
  /** The font family to use for the text (default is `--common-font-family-heading`). */
  fontFamily?: string;
  /** The font weight to use for the text (default is `--common-font-weight-s`). */
  fontWeight?: string;
  /**
   * The line-height used when calculating font-size.
   *
   * Defaults to 1.2 to make sure descendats (ex: "g"), ascendants (ex: "f") and diacritics (ex: "å") are not cut off.
   * Read more: https://m2.material.io/design/typography/understanding-typography.html#type-properties
   *
   * If you override this, make sure the override works with all parks/themes, since they may use different fonts.
   */
  lineHeight?: number;
  /** How to vertically align the content in wrapper (default is `center`).
   * Note: if background is used and background height is set to "fill",
   * then the content will always be vertically centered within the background, and this property will have no effect
   */
  alignItems?: string;
  /** How to horizontally align the content in wrapper (default is `center`). */
  justifyContent?: string;
  /**
   * Background color that adjusts to the size of the content instead of filling the whole wrapper element.
   * Useful for example when the text is long so it fills the whole width but not the height of the wrapper element.
   * Then the background will be proportionally sized to the content instead of filling the whole wrapper element.
   */
  background?: {
    color?: string;
    /** Border radius for the background (default is `var(--common-border-radius-m)`) */
    borderRadius?: string;
    /** Fill wrapper element or fit to content (default is "fitContent"), padding will be applied to the background */
    width?: "fill" | "fitContent";
    /** Fill wrapper element or fit to content (default is "fitContent"), padding will be applied to the background
     * Note: if "fill" is used for height, then the content will always be vertically centered within the background
     */
    height?: "fill" | "fitContent";
  };
};

export const getWidestText = (textArr: Array<string | undefined>): string => {
  if (!textArr.length) return "";

  // Create a temporary div for measuring text width
  const tempDiv = document.createElement("div");
  tempDiv.style.position = "absolute";
  tempDiv.style.visibility = "hidden";
  tempDiv.style.whiteSpace = "nowrap";
  tempDiv.style.fontFamily = `var(--common-font-family-heading)`;
  tempDiv.style.fontWeight = `var(--common-font-weight-s)`;
  document.body.appendChild(tempDiv);

  let widest = "";
  let maxWidth = 0;

  for (const str of textArr) {
    if (!str) continue;
    tempDiv.textContent = str;
    const width = tempDiv.getBoundingClientRect().width;
    if (width > maxWidth) {
      maxWidth = width;
      widest = str;
    }
  }

  document.body.removeChild(tempDiv);
  return widest;
};

/**
 * Checks how big the wrapper is and makes the content as big as possible without overflowing the wrapper.
 * Useful for example texts displayed on screens by Blocks
 *
 * By default, the **parent element** of the component is used as the wrapper. Pass `wrapperElement` to use a
 * different element instead.
 *
 * @returns Div with text that is sized to fit within the wrapper element.
 *
 * @requires
 * - The wrapper element must have a defined width and height for this to work properly.
 *   These values have to be based on the container of the wrapper element, for example using CSS Grid or Flexbox.
 *   Values based on the content of the wrapper element (ex: `width: 100%; height: 100%`) will not work properly and might give incorrect results.
 *
 *   Tip: Use CSS Grid, since default styling is that children stretch to fill the grid it is in.
 *   - Create a CSS class to use on all elements surrounding the AutoSizedText component that has `display: grid; overflow: hidden;`
 *   - The wrapper element must have `overflow: hidden;` to make sure resizing works properly when the wrapper element becomes smaller.
 * - When passing a custom `wrapperElement` prop: the element must be available when the component is rendered.
 *   Use `useState` and not `useRef` to make sure the wrapper element is available.
 *
 * @important
 *    Make sure to test that resizing works properly by example resizing the window several times.
 *    Make sure to test both slow and rapid resizing since it might look okay on some resizing events but then fail on others.
 *    If there is a delay in the resizing it means that some of the requirements above are not met.
 *
 * @remarks
 * - Padding and margins on the wrapper element are not considered.
 *    - Use `padding` prop to add padding around the content instead.
 *    - If you want margin: add a parent to the wrapper element and apply padding/margin to that instead.
 * - Possible to add background color that adjusts to the size of the content instead of filling the whole wrapper element.
 *   Useful for example when the text is long so it fills the whole width but not the height of the wrapper element.
 * - Tip: Use one component for each line of text to get the best result.
 *
 * @sizing Container Sizing Best Practices
 * - **✅ Use CSS Grid for predictable sizing**: `display: grid; grid-template-rows: 1fr 2fr;`
 * - **✅ Use CSS Flexbox with explicit constraints**: `display: flex; flex: 1; height: 100%;`
 * - **⛔ Avoid content-based sizing**: Don't use `width: 100%; height: 100%;` on wrapper elements
 * - **⛔ Avoid fitContent or intrinsic sizing**: Don't use `width: fit-content;` or similar
 *
 * Why avoid `width: 100%; height: 100%;`?
 * - These properties make elements size to their content rather than being constrained by their container
 * - During window resize, this can cause wrapper elements to report old dimensions, causing the calculation to use wrong sizes
 * - AutoSizedText needs container-constrained dimensions to calculate correct font sizes
 * - CSS Grid automatically provides proper container-based sizing without these issues
 *
 * @example
 * ✅ Default usage (no `wrapperElement` prop — parent element is used automatically):
 *   ```tsx
 *      .grid-for-auto-sized-text {
 *          display: grid;
 *          overflow: hidden;
 *      }
 *
 *      <div className={styles.gridForAutoSizedText}>
 *          <AutoSizedText text="Test text" />
 *      </div>
 *   ```
 *
 * @example
 * ✅ Explicit `wrapperElement` prop — useful when the wrapper is not the direct parent:
 *   ```tsx
 *      .container {
 *          width: 100vw;
 *          height: 100vh;
 *          display: grid;
 *      }
 *      .grid-for-auto-sized-text {
 *          display: grid;
 *          overflow: hidden;
 *      }
 *
 *      const [wrapperRef, setWrapperRef] = useState<HTMLDivElement | null>(null);
 *
 *      <div className={multipleClassNames(styles.container, styles.gridForAutoSizedText)}>
 *          <div className={styles.gridForAutoSizedText} ref={setWrapperRef}>
 *              <AutoSizedText wrapperElement={wrapperRef} text="Test text" />
 *          </div>
 *      </div>
 *   ```
 *
 * @example
 * ⛔ Don't:
 *    ```tsx
 *      .container {
 *          width: 100%;
 *          height: 100%;
 *          display: grid;
 *      }
 *      .wrapper {
 *          display: grid;
 *          overflow: hidden;
 *      }
 *
 *       const wrapperRef = useRef<HTMLDivElement>(null);
 *       const wrapperElement = wrapperRef.current;
 *
 *       <div className={styles.container}>
 *           <div className={styles.wrapper} ref={wrapperRef}>
 *               <AutoSizedText wrapperElement={wrapperElement} text={text} />
 *           </div>
 *       </div>
 *    ```
 */
const AutoSizedText = ({
  wrapperElement: wrapperElementOverride,
  text,
  widestText,
  strikeThroughText,
  icon,
  gap = 20,
  padding = "2",
  paddingMode = "fixedWidth",
  fontFamily = `var(--common-font-family-heading)`,
  fontWeight = `var(--common-font-weight-s)`,
  lineHeight = 1.2,
  alignItems = "center",
  justifyContent = "center",
  background,
}: AutoSizedTextProps) => {
  const [divRef, setDivRef] = useState<HTMLDivElement | null>(null);
  const wrapperElement = wrapperElementOverride ?? divRef?.parentElement ?? null;

  const itemsCalculation = useMemo(() => {
    const items = [icon !== undefined, Boolean(strikeThroughText), text !== ""].filter(Boolean);
    const itemCount = items.length;
    const numberOfGaps = itemCount > 0 ? itemCount - 1 : 0;
    const contentGap = numberOfGaps > 0 ? gap / 100 : 0;
    return { itemCount, numberOfGaps, contentGap };
  }, [icon, strikeThroughText, text, gap]);

  const { numberOfGaps, contentGap } = itemsCalculation;
  const minFontSize = 1;
  const maxFontSize = 10000;
  const [fontSize, setFontSize] = useState(minFontSize);
  const [finalPadding, setFinalPadding] = useState("");
  const whiteSpace = "nowrap";

  // Set default values for background
  if (background) {
    background.borderRadius = background?.borderRadius ?? "var(--common-border-radius-m)";
    background.width = background?.width ?? "fitContent";
    background.height = background?.height ?? "fitContent";
  }

  const updateFontSize = useCallback(() => {
    if (!wrapperElement) {
      return;
    }

    // Get fresh dimensions for most accurate values
    // Get computed style so that sizing is correct even for warped elements (example slides is swiper)
    const style = getComputedStyle(wrapperElement);
    const currentWidth = Number(style.width.replace("px", ""));
    const currentHeight = Number(style.height.replace("px", ""));

    if (currentWidth === 0 || currentHeight === 0) {
      return;
    }

    // Get total width of gaps between elements
    const totalGap = numberOfGaps * (fontSize * contentGap);

    function getPaddingPx(padding: number, wrapperSize: number): number {
      return Math.floor((padding / 100) * wrapperSize);
    }

    /** Get all padding values (top, right, bottom, left), using standars css syntax, based on padding mode */
    function getAllPaddingValues(
      padding: string,
      paddingMode: string,
      width: number,
      height: number,
    ): [number, number, number, number] {
      const values = padding.split(" ").map((p) => parseInt(p, 10));
      let useHeight: number;
      let useWidth: number;
      switch (paddingMode) {
        case "fixedHeight":
          useHeight = height;
          useWidth = height;
          break;
        case "dynamic":
          useHeight = height;
          useWidth = width;
          break;
        case "fixedWidth":
        default:
          useHeight = width;
          useWidth = width;
          break;
      }

      if (values.length === 2)
        return [
          getPaddingPx(values[0], useHeight),
          getPaddingPx(values[1], useWidth),
          getPaddingPx(values[0], useHeight),
          getPaddingPx(values[1], useWidth),
        ];
      if (values.length === 3)
        return [
          getPaddingPx(values[0], useHeight),
          getPaddingPx(values[1], useWidth),
          getPaddingPx(values[2], useHeight),
          getPaddingPx(values[1], useWidth),
        ];
      if (values.length === 4)
        return [
          getPaddingPx(values[0], useHeight),
          getPaddingPx(values[1], useWidth),
          getPaddingPx(values[2], useHeight),
          getPaddingPx(values[3], useWidth),
        ];
      return [
        getPaddingPx(values[0], useHeight),
        getPaddingPx(values[0], useWidth),
        getPaddingPx(values[0], useHeight),
        getPaddingPx(values[0], useWidth),
      ];
    }
    const [paddingTop, paddingRight, paddingBottom, paddingLeft] = getAllPaddingValues(
      padding,
      paddingMode,
      currentWidth,
      currentHeight,
    );
    setFinalPadding(`${paddingTop}px ${paddingRight}px ${paddingBottom}px ${paddingLeft}px`);

    // Make sure paddings and gaps are included when checking for the biggest font size that fits
    const targetHeight = Math.floor(currentHeight - paddingTop - paddingBottom);
    const targetWidth = Math.floor(currentWidth - paddingLeft - paddingRight - totalGap);

    const temp = document.createElement("div");
    Object.assign(temp.style, {
      position: "absolute",
      visibility: "hidden",
      boxSizing: "border-box",
      display: "flex",
      alignItems,
      justifyContent,
      gap: `${fontSize * contentGap}px`,
      whiteSpace,
      fontFamily,
      fontWeight,
      lineHeight,
    });
    temp.style.setProperty("--icon-font-size", `${fontSize}px`);

    if (icon !== undefined) {
      // Use a placeholder span for sizing
      const iconSpan = document.createElement("span");
      Object.assign(iconSpan.style, {
        boxSizing: "border-box",
        display: "inline-block",
        width: "1em",
        height: "1em",
        fontSize: `${fontSize}px`,
      });
      temp.appendChild(iconSpan);
    }

    if (strikeThroughText) {
      const strikeThroughTextSpan = document.createElement("span");
      Object.assign(strikeThroughTextSpan.style, {
        boxSizing: "border-box",
      });
      strikeThroughTextSpan.textContent = strikeThroughText;
      temp.appendChild(strikeThroughTextSpan);
    }

    if (text) {
      const textSpan = document.createElement("span");
      Object.assign(textSpan.style, {
        boxSizing: "border-box",
      });
      textSpan.textContent = widestText || text;
      temp.appendChild(textSpan);
    }

    wrapperElement.appendChild(temp);

    const fits = (size: number) => {
      Array.from(temp.children).forEach((child) => {
        (child as HTMLElement).style.fontSize = `${size}px`;
      });
      temp.style.fontSize = `${size}px`;
      const style = getComputedStyle(temp);
      const width = Number(style.width.replace("px", ""));
      const height = Number(style.height.replace("px", ""));
      return width <= targetWidth && height <= targetHeight;
    };

    // Binary search for the largest font size that fits within the target width and height
    let low = minFontSize;
    let high = maxFontSize;
    let bestFit = minFontSize;

    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      if (fits(mid)) {
        bestFit = mid;
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }

    wrapperElement.removeChild(temp);

    // Set the font size to the best fit found
    setFontSize(bestFit);
  }, [
    wrapperElement,
    text,
    widestText,
    strikeThroughText,
    padding,
    fontFamily,
    fontWeight,
    lineHeight,
    alignItems,
    justifyContent,
    icon,
    contentGap,
    fontSize,
    numberOfGaps,
    paddingMode,
  ]);

  useEffect(() => {
    if (!wrapperElement) return undefined;

    // Trigger initial update on element mount
    updateFontSize();

    // Update font size if the wrapper element is resized (with debouncing for smooth transitions)
    const debouncedOnResize = debounce(updateFontSize, 100);
    const resizeObserver = new ResizeObserver(debouncedOnResize);
    resizeObserver.observe(wrapperElement);

    return () => {
      resizeObserver.disconnect();
    };
  }, [wrapperElement, updateFontSize]);

  return (
    <div
      className={styles.wrapper}
      style={{
        // If background height is set to fill, then the content will always be vertically centered within the wrapper
        alignItems: alignItems,
        justifyContent: justifyContent,
      }}
      ref={setDivRef}
    >
      <div
        className={styles.autoSize}
        style={
          {
            // Use fit content as default for height and width, to be able to position text within wrapper
            width: background?.width === "fill" ? "100%" : "fit-content",
            height: background?.height === "fill" ? "100%" : "fit-content",
            justifyContent: justifyContent,
            fontSize: `${fontSize}px`,
            gap: `${fontSize * contentGap}px`,
            padding: finalPadding,
            background: background?.color ?? "none",
            borderRadius: background?.borderRadius ?? "none",
            "--icon-font-size": `${fontSize}px`,
          } as React.CSSProperties
        }
      >
        {icon !== undefined && <Icon name={icon} />}

        {strikeThroughText && (
          <s className={styles.text} role="deletion">
            {strikeThroughText}
          </s>
        )}

        {text !== "" && (
          <span className={styles.text} style={{ fontFamily, fontWeight, lineHeight }}>
            {text}
          </span>
        )}
      </div>
    </div>
  );
};

export default AutoSizedText;
